/* Entradas y salidas: cada 12-25 min sale un nick y entra uno nuevo del pool diario */
let lastSwap = 0;
function maybeSwapNicks(){
  try{
    const now = Date.now();
    if(now - lastSwap < (12 + Math.random()*13)*60*1000) return;
    lastSwap = now;
    const daily = getDaily(), cur = getActive();
    const outsiders = daily.filter(x => cur.indexOf(x) === -1);
    if(!outsiders.length || cur.length < 2) return;
    const leaver = cur[Math.floor(Math.random()*cur.length)];
    const joiner = outsiders[Math.floor(Math.random()*outsiders.length)];
    const idx = activeSet.indexOf(leaver);
    if(idx >= 0) activeSet[idx] = joiner;
    if(botsOn && amLeader() && now - lastHumanTs < 30*60*1000 && window.JOIN_MSGS && Math.random() < 0.7){
      const text = pickFrom(window.JOIN_MSGS).replaceAll("{prog}", progName());
      if(!botDup(text)){ botMark(text); sb.from("messages").insert({nick: joiner.nick, text: text}); }
    }
  }catch(e){}
}

/* Si el humano le habla a un nick por su nombre ("Rulo, ¿de dónde sos?"), responde ESE nick */
function findDirectedNick(t){
  let best = null, bestLen = 0;
  personas.forEach(p=>{
    const nl = p.nick.toLowerCase();
    const variants = [nl];
    const first = nl.split(/\s+/)[0];
    if(first !== nl) variants.push(first);
    const stripped = nl.replace(/(rc|mx|ar|ok)$/, "");
    if(stripped !== nl && stripped.length >= 3) variants.push(stripped);
    variants.forEach(v=>{
      if(v.length < 3) return;
      const esc = v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      try{
        const re = new RegExp("(?<![a-záéíóúñü])" + esc + "(?![a-záéíóúñü])");
        if(re.test(t) && v.length > bestLen){ best = p; bestLen = v.length; }
      }catch(e){}
    });
  });
  return best;
}
/* Hilo de conversación: si el humano sigue hablando sin nombrar a otro nick,
   continúa respondiendo el mismo nick (como en una charla real) */
let lastConvo = {human:"", bot:"", ts:0};
function findThreadNick(mNick, directedNick, now){
  if(directedNick) return null;
  if(lastConvo.human===mNick && lastConvo.bot && now-lastConvo.ts<3e5){
    const f = personas.filter(pp=>pp.nick===lastConvo.bot);
    if(f.length) return f[0];
  }
  return null;
}
